public function storeView(Request$r):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['name'=>['required','string','max:255'],'report_kind'=>['required',Rule::in(['analytics_snapshots','workforce_plans','data_quality'])],'filters'=>['nullable','array'],'filters.metric_code'=>['nullable','string','max:100'],'filters.dimension'=>['nullable',Rule::in(['organization_unit','location','staff_type','tenure_band'])],'filters.as_of_from'=>['nullable','date'],'filters.as_of_to'=>['nullable','date'],'filters.status'=>['nullable','string','max:60'],'filters.issue_type'=>['nullable','string','max:100'],'columns'=>['required','array','min:1'],'columns.*'=>['required','string','distinct'],'visibility'=>['required',Rule::in(['private','company'])]]);abort_unless($r->user()->can($this->access->permission($d['report_kind'])),403);abort_if(array_diff(array_keys($d['filters']??[]),self::KIND_FILTERS[$d['report_kind']]),422,'A report filter is not valid for this report kind.');abort_if(array_diff($d['columns'],self::KIND_COLUMNS[$d['report_kind']]),422,'A report column is not valid for this report kind.');$filters=$d['filters']??[];if(isset($filters['as_of_from'],$filters['as_of_to']))abort_unless($filters['as_of_to']>=$filters['as_of_from'],422,'Report as-of range is invalid.');if($d['visibility']==='company')abort_unless($r->user()->can('hr.reporting.manage'),403);$payload=['report_kind'=>$d['report_kind'],'filters'=>$filters,'columns'=>$d['columns'],'visibility'=>$d['visibility']];$id=(string)Str::uuid();DB::table('hr_report_saved_views')->insert(['id'=>$id,'company_id'=>$a->company_id,'owner_user_id'=>$r->user()->id,'name'=>$d['name'],'report_kind'=>$d['report_kind'],'filter_contract'=>json_encode($filters,JSON_THROW_ON_ERROR),'column_contract'=>json_encode($d['columns'],JSON_THROW_ON_ERROR),'visibility'=>$d['visibility'],'status'=>'active','view_checksum'=>hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)),'created_at'=>now(),'updated_