public function storeSchedule(Request$r):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['saved_view_id'=>['required','uuid'],'name'=>['required','string','max:255'],'cadence'=>['required',Rule::in(['daily','weekly','monthly'])],'timezone'=>['required','timezone'],'local_time'=>['required','date_format:H:i'],'day_of_week'=>['nullable','required_if:cadence,weekly','integer','between:0,6'],'day_of_month'=>['nullable','required_if:cadence,monthly','integer','between:1,28'],'format'=>['required',Rule::in(['csv','xlsx','pdf'])],'recipient_user_ids'=>['required','array','min:1','max:100'],'recipient_user_ids.*'=>['required','uuid','distinct'],'delivery_channel'=>['required',Rule::in(['in_app','email'])]]);$view=DB::table('hr_report_saved_views')->where('id',$d['saved_view_id'])->where('company_id',$a->company_id)->where('status','active')->where(fn($q)=>$q->where('owner_user_id',$r->user()->id)->orWhere('visibility','company'))->first();abort_unless($view,422,'Saved view is not available for scheduling.');abort_unless($r->user()->can($this->access->permission($view->report_kind)),403);foreach($d['recipient_user_ids']as$userId)abort_unless($this->access->userAuthorized($userId,$a->company_id,$view->report_kind,true),422,'Every recipient must remain active and authorized to export this report kind.');$payload=$this->schedulePayload($d,$view->view_checksum);$checksum=hash('sha256',json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$id=(string)Str::uuid();DB::table('hr_report_schedules')->insert(['id'=>$id,'company_id'=>$a->company_id,'saved_view_id'=>$view->id,'name'=>$d['name'],'cadence'=>$d['cadence'],'timezone'=>$d['timezone'],'local_time'=>$d['local_time'],'day_of_week'=>$d['day_of_week']??null,'day_of_month'=>$d['day_of_month']??null,'format'=>$d['format'],'recipient_user_ids'=>json_encode($d['recipient_user_ids'],JSON_THROW_ON_ERROR),'delivery_channel'=>$d['delivery_channel'],'next_due_at'=>$this->nextDue($d),'status'=>'pending_approva