public function decideSchedule(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['decision'=>['required',Rule::in(['approved','rejected','disabled'])],'reason'=>['required','string','max:3000']]);return DB::transaction(function()use($r,$a,$id,$d){$s=DB::table('hr_report_schedules')->where('id',$id)->where('company_id',$a->company_id)->lockForUpdate()->first();abort_unless($s,404);$allowed=['pending_approval'=>['approved','rejected'],'approved'=>['disabled']];abort_unless(in_array($d['decision'],$allowed[$s->status]??[],true),409);abort_if($d['decision']==='approved'&&$s->created_by===$r->user()->id,409,'Schedule creator cannot approve the same schedule.');$view=DB::table('hr_report_saved_views')->where('id',$s->saved_view_id)->where('company_id',$a->company_id)->where('status','active')->first();abort_unless($view,409,'Scheduled view is no longer active.');$recipients=json_decode($s->recipient_user_ids,true)?:[];$contract=['saved_view_id'=>$s->saved_view_id,'name'=>$s->name,'cadence'=>$s->cadence,'timezone'=>$s->timezone,'local_time'=>substr($s->local_time,0,5),'day_of_week'=>$s->day_of_week,'day_of_month'=>$s->day_of_month,'format'=>$s->format,'recipient_user_ids'=>$recipients,'delivery_channel'=>$s->delivery_channel];$checksum=hash('sha256',json_encode($this->schedulePayload($contract,$view->view_checksum),JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));abort_unless(hash_equals($s->schedule_checksum,$checksum),409,'Schedule content or saved-view version changed after submission.');if($d['decision']==='approved')foreach($recipients as$userId)abort_unless($this->access->userAuthorized($userId,$a->company_id,$view->report_kind,true),409,'A report recipient is no longer active and authorized.');$updates=['status'=>$d['decision'],'approved_by'=>$r->user()->id,'approved_at'=>now(),'decision_reason'=>$d['reason'],'updated_at'=>now()];if($d['decision']==='approved')$updates['next_due_at']=$this->nextDue($contract);DB::table('hr_report_sc