public function requestExport(Request$r,string$id):JsonResponse{$this->enabled();$a=$this->actor($r);$d=$r->validate(['as_of_date'=>['required','date'],'format'=>['required',Rule::in(['csv','xlsx','pdf'])],'idempotency_key'=>['required','string','max:160']]);$view=DB::table('hr_report_saved_views')->where('id',$id)->where('company_id',$a->company_id)->where('status','active')->where(fn($q)=>$q->where('owner_user_id',$r->user()->id)->orWhere('visibility','company'))->first();abort_unless($view,404);abort_unless($r->user()->can($this->access->permission($view->report_kind)),403);return response()->json(['status'=>'success','data'=>$this->runs->queue($view,null,$d['as_of_date'],$d['format'],$r->user()->id,$d['idempotency_key'])],201);}
