public function download(Request$r,string$id):mixed{$a=$this->actor($r);$run=DB::table('hr_report_runs as run')->join('hr_report_saved_views as view','view.id','=','run.saved_view_id')->where('run.id',$id)->where('run.company_id',$a->company_id)->select(['run.*','view.report_kind'])->first();abort_unless($run,404);abort_unless($r->user()->can($this->access->permission($run->report_kind)),403);$recipient=DB::table('hr_report_delivery_events')->where('report_run_id',$id)->where('recipient_user_id',$r->user()->id)->exists();abort_unless($run->requested_by===$r->user()->id||$recipient||$r->user()->can('hr.reporting.manage'),403);abort_unless($run->status==='completed'&&$run->artifact_path&&$run->artifact_expires_at&&now()->lt($run->artifact_expires_at),410,'Report artifact is not available or has expired.');abort_unless(Storage::disk($run->artifact_disk)->exists($run->artifact_path),404);$content=Storage::disk($run->artifact_disk)->get($run->artifact_path);abort_unless(hash_equals($run->artifact_checksum,hash('sha256',$content)),409,'Report artifact integrity verification failed.');DB::table('hr_report_delivery_events')->insert(['id'=>(string)Str::uuid(),'report_run_id'=>$id,'recipient_user_id'=>$r->user()->id,'channel'=>'download','event_type'=>'downloaded','artifact_checksum'=>$run->artifact_checksum,'actor_user_id'=>$r->user()->id,'occurred_at'=>now()]);return response($content,200,['Content-Type'=>$run->artifact_mime,'Content-Disposition'=>'attachment; filename="'.str_replace('"','',$run->artifact_file_name).'"']);}
