private function schedulePayload(array$d,string$viewChecksum):array{return['saved_view_id'=>$d['saved_view_id'],'name'=>$d['name'],'cadence'=>$d['cadence'],'timezone'=>$d['timezone'],'local_time'=>substr($d['local_time'],0,5),'day_of_week'=>$d['cadence']==='weekly'?(int)$d['day_of_week']:null,'day_of_month'=>$d['cadence']==='monthly'?(int)$d['day_of_month']:null,'format'=>$d['format'],'recipient_user_ids'=>array_values($d['recipient_user_ids']),'delivery_channel'=>$d['delivery_channel'],'view_checksum'=>$viewChecksum];}
private function nextDue(array$d):\Carbon\CarbonImmutable{$now=\Carbon\CarbonImmutable::now($d['timezone']);[$hour,$minute]=array_map('intval',explode(':',substr($d['local_time'],0,5)));$candidate=$now->setTime($hour,$minute,0);if($d['cadence']==='daily'){if($candidate->lessThanOrEqualTo($now))$candidate=$candidate->addDay();}elseif($d['cadence']==='weekly'){$candidate=$candidate->nextOrSame((int)$d['day_of_week']);if($candidate->lessThanOrEqualTo($now))$candidate=$candidate->addWeek();}else{$day=(int)$d['day_of_month'];$candidate=$candidate->setDay($day);if($candidate->lessThanOrEqualTo($now))$candidate=$candidate->addMonthNoOverflow()->setDay($day);}return$candidate->utc();}
